# Generate fixtures with R's `log1p` on the shared inputs in `../inputs/`.
#
# ## Notes
#
# -   Inputs are read only through `jsonlite::fromJSON`, never with
#     `as.numeric`, `scan`, or decimal literals, since R's own decimal
#     conversion can misread values by 1 ULP or more on some platforms.
# -   Outputs are written with `sprintf( "%.17g" )`, which round-trips.
# -   R returns NaN (with a warning) rather than raising, so no errors are
#     recorded.

# Set the precision to 16 digits:
options( digits = 16L );

#' Generate test fixtures.
#'
#' @examples
#' main();
main <- function() {
	#' Get the script filepath.
	#'
	#' @return The absolute path of this script
	#'
	#' @examples
	#' filepath <- get_script_path();
	get_script_path <- function() {
		args <- commandArgs( trailingOnly = FALSE );
		needle <- '--file=';
		match <- grep( needle, args );
		if ( length( match ) > 0L ) {
			# Rscript:
			filepath <- sub( needle, '', args[match] );
		} else {
			ls_vars <- ls( sys.frames()[[1L]] )
			if ( 'fileName' %in% ls_vars ) {
				# Source'd via RStudio:
				filepath <- sys.frames()[[1]]$fileName; # nolint
			} else {
				# Source'd via R console:
				filepath <- sys.frames()[[1L]]$ofile;
			}
		}
		return( normalizePath( filepath ) );
	}

	#' Decode a JSON value from a shared input file as a double.
	#'
	#' @param v value parsed by jsonlite
	#' @return double
	decode <- function( v ) {
		if ( is.character( v ) ) {
			if ( v == 'NaN' ) {
				return( NaN );
			}
			if ( v == 'Infinity' ) {
				return( Inf );
			}
			if ( v == '-Infinity' ) {
				return( -Inf );
			}
			stop( paste( 'unexpected string in inputs:', v ) );
		}
		return( as.double( v ) );
	}

	#' Encode a double as a JSON value, matching the shared input files.
	#'
	#' @param x double
	#' @return JSON value
	encode <- function( x ) {
		if ( is.nan( x ) ) {
			return( '"NaN"' );
		}
		if ( is.na( x ) ) {
			return( 'null' );
		}
		if ( x == Inf ) {
			return( '"Infinity"' );
		}
		if ( x == -Inf ) {
			return( '"-Infinity"' );
		}
		return( sprintf( '%.17g', x ) );
	}

	#' Return the C library's name and version, if known.
	#'
	#' @return string or NULL
	libc <- function() {
		v <- tryCatch( system( 'getconf GNU_LIBC_VERSION', intern = TRUE, ignore.stderr = TRUE ), error = function( e ) character( 0L ), warning = function( w ) character( 0L ) );
		if ( length( v ) == 1L ) {
			return( v );
		}
		return( NULL );
	}

	#' Read a shared input file, and write fixtures to a file of the same name.
	#'
	#' @param name filename
	gen <- function( name ) {
		inpath <- file.path( inputs, name );
		data <- jsonlite::fromJSON( inpath, simplifyVector = FALSE );
		x <- vapply( data$x, decode, numeric( 1L ) );
		y <- suppressWarnings( log1p( x ) );

		meta <- list(
			source = 'r::base',
			`function` = 'log1p',
			implementation = "the C library's log1p",
			versions = list(
				r = paste( R.version$major, R.version$minor, sep = '.' ),
				jsonlite = as.character( utils::packageVersion( 'jsonlite' ) )
			),
			platform = list(
				os = tolower( Sys.info()[[ 'sysname' ]] ),
				arch = R.version$arch,
				compiler = NULL,
				libc = libc()
			),
			generated = format( Sys.time(), '%Y-%m-%dT%H:%M:%SZ', tz = 'UTC' ),
			inputs = as.character( tools::sha256sum( inpath ) ),
			regime = data$regime
		);

		out <- paste0(
			'{"x":[', paste( vapply( x, encode, character( 1L ) ), collapse = ',' ), ']',
			',"expected":[', paste( vapply( y, encode, character( 1L ) ), collapse = ',' ), ']',
			',"meta":', jsonlite::toJSON( meta, auto_unbox = TRUE, null = 'null' ),
			'}'
		);
		writeLines( out, file.path( source_dir, name ) );
	}

	# Get the directory of this script:
	source_dir <- dirname( get_script_path() );

	# Shared inputs:
	inputs <- file.path( source_dir, '..', 'inputs' );

	for ( name in sort( list.files( inputs, pattern = '\\.json$' ) ) ) {
		gen( name );
	}
}

main();
